const grid = [
  [1, 2, 3],
  [4, 5, 6],
]
const columns = []
for (let c = 0; c < grid[0].length; c++) {
  const column = []
  for (let r = 0; r < grid.length; r++) column.push(grid[r][c])
  columns.push(column)
}
console.log(columns)

